/**
 * Lint rules give the same findings in WASM as natively (lint-core-plan.md C5.5).
 *
 * The expectations are generated by running the native runner
 * (`scripts/gen-lint-parity-fixture.py`) over two kinds of case:
 *
 * - `example`: every example of the built-in rules and of
 *   `tests/data/lint-examples/*.yaml`. Here each one runs as
 *   `pssparser.lint.examples` runs it natively: parsed and linked on its
 *   own, only its rule enabled. It must pass its `// expect:` comments, and
 *   give the native markers.
 * - `run`: rule files, a model and a request; the markers, statistics
 *   (without the time) and request problems must be the native ones.
 *
 * Markers are compared in a normal form: file name, sorted.
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { beforeAll, describe, expect, it } from 'vitest';
import {
  createParser,
  initPssParser,
  ParseException,
  type LintRequest,
  type Marker,
  type Parser,
} from '../src/index.js';

interface NormalMarker {
  code: string;
  severity: string;
  message: string;
  file: string;
  line: number;
  col: number;
  extent: number;
}

interface ExampleCase {
  id: string;
  kind: 'example';
  rule: string;
  name: string;
  file: string;
  line: number;
  col: number;
  ok: boolean;
  markers: NormalMarker[];
}

interface RunCase {
  id: string;
  kind: 'run';
  ruleFiles: string[];
  ruleTexts: Array<{ name: string; text: string }>;
  sources: Array<{ name: string; text: string }>;
  request: LintRequest;
  markers: NormalMarker[];
  stats: Array<{ id: string; matches: number; findings: number; steps: number; errors: number }>;
  problems: string[];
}

/** An example as the engine's `rulesJson` gives it. */
interface RuleExample {
  name: string;
  line: number;
  col: number;
  files: Array<{ name: string; text: string; expect: Array<{ id: string; line: number; col: number }> }>;
}

interface RuleInfo {
  id: string;
  file: string;
  examples: RuleExample[];
}

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(here, '..', '..');
const fixture = JSON.parse(readFileSync(join(here, 'fixtures', 'lint-parity.json'), 'utf8')) as {
  ruleFiles: string[];
  cases: Array<ExampleCase | RunCase>;
};
const examples = fixture.cases.filter((c): c is ExampleCase => c.kind === 'example');
const runs = fixture.cases.filter((c): c is RunCase => c.kind === 'run');

const ruleFile = (path: string) => ({ name: path, text: readFileSync(join(repoRoot, path), 'utf8') });

function normal(markers: readonly Marker[]): NormalMarker[] {
  const out = markers.map((m) => ({
    code: m.code ?? '',
    severity: m.severity,
    message: m.message,
    file: m.file,
    line: m.line,
    col: m.col,
    extent: m.extent,
  }));
  const key = (m: NormalMarker) => [m.file, m.line, m.col, m.code, m.message] as const;
  return out.sort((a, b) => {
    const [x, y] = [key(a), key(b)];
    for (let i = 0; i < x.length; i++) {
      if (x[i] !== y[i]) {
        return x[i] < y[i] ? -1 : 1;
      }
    }
    return 0;
  });
}

/** Parse and link, keeping the markers of a model with errors. */
function parseAndLink(parser: Parser, sources: Array<{ name: string; text: string }>): void {
  try {
    parser.parseSources(sources.map((s) => ({ name: s.name, content: s.text })));
    parser.link();
  } catch (e) {
    if (!(e instanceof ParseException)) {
      throw e;
    }
  }
}

/**
 * Whether `found` is exactly what `expect` says, as
 * `pssparser.lint.examples.compare` decides it: an expectation with column 0
 * matches anywhere on its line, and exact ones are matched first.
 */
function matches(
  expect: Array<[string, number, number]>,
  found: Array<[string, number, number]>,
): boolean {
  const left = [...found];
  const ordered = [...expect].sort((a, b) => Number(a[2] === 0) - Number(b[2] === 0));
  for (const [file, line, col] of ordered) {
    const i = left.findIndex((g) => g[0] === file && g[1] === line && (col === 0 || col === g[2]));
    if (i < 0) {
      return false;
    }
    left.splice(i, 1);
  }
  return left.length === 0;
}

let rules: RuleInfo[];
beforeAll(async () => {
  const module = await initPssParser();
  const session = new module.ParserSession();
  try {
    for (const f of fixture.ruleFiles.map(ruleFile)) {
      session.loadRuleFile(f.name, f.text);
    }
    expect(JSON.parse(session.ruleDiagnosticsJson())).toEqual([]);
    rules = JSON.parse(session.rulesJson()) as RuleInfo[];
  } finally {
    session.delete();
  }
});

describe('rule examples (WASM)', () => {
  it('are the examples the native build ran', () => {
    const here = rules.flatMap((r) =>
      r.examples.map((x) => `example:${r.id}:${x.name}@${r.file}:${x.line}:${x.col}`),
    );
    expect(here).toEqual(examples.map((c) => `${c.id}@${c.file}:${c.line}:${c.col}`));
  });

  it.each(examples.map((c) => [c.id, c] as const))('%s', async (_id, c) => {
    const rule = rules.find((r) => r.id === c.rule)!;
    const example = rule.examples.find((x) => x.name === c.name)!;
    using parser = await createParser();
    parser.loadRules(fixture.ruleFiles.map(ruleFile));
    parseAndLink(parser, example.files);
    expect(parser.markers.filter((m) => m.severity === 'error')).toEqual([]);
    const result = parser.runLint({ enabled: [c.rule] });
    const markers = normal(result.markers);
    expect(markers).toEqual(c.markers);
    const found = markers
      .filter((m) => m.code === c.rule)
      .map((m) => [m.file, m.line, m.col] as [string, number, number]);
    const expected = example.files.flatMap((f) =>
      f.expect.map((e) => [f.name, e.line, e.col] as [string, number, number]),
    );
    expect(matches(expected, found) && markers.every((m) => m.code === c.rule)).toBe(c.ok);
    expect(c.ok).toBe(true);
  });
});

describe('lint runs (WASM)', () => {
  it.each(runs.map((c) => [c.id, c] as const))('%s', async (_id, c) => {
    using parser = await createParser();
    expect(parser.loadRules([...c.ruleFiles.map(ruleFile), ...c.ruleTexts])).toEqual([]);
    parseAndLink(parser, c.sources);
    const result = parser.runLint(c.request);
    expect(normal(result.markers)).toEqual(c.markers);
    expect(result.stats.map(({ ns: _ns, ...s }) => s)).toEqual(c.stats);
    expect(result.problems).toEqual(c.problems);
  });
});
